actions.script:
const theRoster = ec.context.get('roster') || {}
const lanes = Array.from(theRoster.lanes || [])
const shifts = Array.from(theRoster.shifts || [])
const dayCount = Number(theRoster.days || 7)
const addDay = (day, count) => {
    const [y, m, d] = String(day).split('-').map(Number)
    return new Date(Date.UTC(y, m - 1, d + count)).toISOString().substring(0, 10)
}
const weekdays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
const titleOf = (day) => ec.l10n.localize(weekdays[new Date(day + 'T12:00:00Z').getUTCDay()]) + ' ' + day.substring(5)
const cellOf = (lane, day) => {
    const parts = shifts.filter((row) => row.partyRelationshipId === lane.partyRelationshipId && String(row.startText).substring(0, 10) === day)
        .map((row) => String(row.startText).substring(11, 16) + '–' + String(row.endText).substring(11, 16)
            + (row.statusEnumId === 'ShsDraft' ? ' (' + ec.l10n.localize('draft') + ')' : '') + (row.facilityName ? ' ' + row.facilityName : ''))
    for (const row of Array.from(lane.leaveList || []).filter((item) => item.day === day))
        parts.push(ec.l10n.localize('Leave') + (row.partText === 'Whole day' ? '' : ' (' + ec.l10n.localize(row.partText.toLowerCase()) + ')'))
    for (const row of Array.from(lane.holidayList || []).filter((item) => item.day === day)) parts.push(row.name)
    return parts.join('; ')
}
rosterWeeks = []
for (let start = 0; theRoster.fromDay && start < dayCount; start += 7) {
    const days = [0, 1, 2, 3, 4, 5, 6].map((i) => addDay(theRoster.fromDay, start + i))
    rosterWeeks.push({title: days[0] + ' – ' + days[6], dayTitles: days.map(titleOf),
        rows: lanes.map((lane) => Object.assign({personName: lane.personName, organizationName: lane.organizationName,
            hoursText: lane.hours ? lane.hours + ' h' : ''}, Object.fromEntries(days.map((day, i) => ['d' + i, cellOf(lane, day)]))))})
}
